from pathlib import Path

index_path = Path('server/employee-portal/index.html')
css_path = Path('server/employee-portal/portal-v6.css')

html = index_path.read_text(encoding='utf-8')
css = css_path.read_text(encoding='utf-8')

marker = 'DOWNLOAD_REQUIREMENTS_V1'
if marker not in html:
    anchor = '''        <article class="download-card surface reveal delay-3" data-platform="android"><div class="platform-symbol android-symbol"><span></span><i></i><i></i></div><small>MOBILE</small><h3>Android</h3><p>Мобильный доступ к чатам, задачам и данным компании.</p><div class="platform-meta"><span id="androidSize">—</span><span>APK · Android</span></div><button class="download-button" data-download="android" disabled><span>Скачать для Android</span></button></article>\n      </div>'''
    replacement = '''        <article class="download-card surface reveal delay-3" data-platform="android"><div class="platform-symbol android-symbol"><span></span><i></i><i></i></div><small>MOBILE</small><h3>Android</h3><p>Мобильный доступ к чатам, задачам и данным компании.</p><div class="platform-meta"><span id="androidSize">—</span><span>APK · Android</span></div><button class="download-button" data-download="android" disabled><span>Скачать для Android</span></button></article>\n\n        <!-- DOWNLOAD_REQUIREMENTS_V1 -->\n        <section class="download-requirements surface reveal" aria-labelledby="downloadRequirementsTitle">\n          <div class="requirements-title">\n            <span class="section-label">СИСТЕМНЫЕ ТРЕБОВАНИЯ</span>\n            <h3 id="downloadRequirementsTitle">Перед установкой</h3>\n            <p>Минимальные и рекомендуемые параметры для текущих сборок WesiOS. Публикуем только подтверждённые ограничения.</p>\n          </div>\n          <div class="requirements-grid">\n            <article class="req-card surface">\n              <div class="req-platform"><b>Windows</b><span>x64</span></div>\n              <div class="req-cols">\n                <div><small>МИНИМАЛЬНО</small><dl>\n                  <dt>ОС</dt><dd>Windows 10, 64-bit</dd>\n                  <dt>Архитектура</dt><dd>x64</dd>\n                  <dt>ОЗУ</dt><dd>Порог WesiOS не задан</dd>\n                  <dt>Диск</dt><dd>Сборка + локальные данные</dd>\n                  <dt>Сеть</dt><dd>Для входа и синхронизации</dd>\n                </dl></div>\n                <div class="recommended"><small>РЕКОМЕНДУЕТСЯ</small><dl>\n                  <dt>ОС</dt><dd>Windows 11, 64-bit</dd>\n                  <dt>Накопитель</dt><dd>SSD</dd>\n                  <dt>Сеть</dt><dd>Стабильное подключение</dd>\n                  <dt>ОЗУ / CPU</dt><dd>Без искусственного порога</dd>\n                </dl></div>\n              </div>\n            </article>\n            <article class="req-card surface">\n              <div class="req-platform"><b>Android</b><span>API 21+</span></div>\n              <div class="req-cols">\n                <div><small>МИНИМАЛЬНО</small><dl>\n                  <dt>ОС</dt><dd>Android 5.0 (API 21)</dd>\n                  <dt>ОЗУ</dt><dd>Порог WesiOS не задан</dd>\n                  <dt>Диск</dt><dd>APK + локальные данные</dd>\n                  <dt>Сеть</dt><dd>Для входа и синхронизации</dd>\n                </dl></div>\n                <div class="recommended"><small>РЕКОМЕНДУЕТСЯ</small><dl>\n                  <dt>ОС</dt><dd>Android 10 или новее</dd>\n                  <dt>Архитектура</dt><dd>ARM64</dd>\n                  <dt>Обновления</dt><dd>Актуальные системные патчи</dd>\n                  <dt>Сеть</dt><dd>Стабильное подключение</dd>\n                </dl></div>\n              </div>\n            </article>\n          </div>\n          <p class="requirements-proof">Android minimum подтверждён <code>minSdkVersion 21</code>. Windows release собирается как <code>x64</code>. Рекомендованные параметры не являются блокировкой запуска.</p>\n        </section>\n      </div>'''
    if anchor not in html:
        raise SystemExit('dashboard anchor not found')
    html = html.replace(anchor, replacement, 1)
    index_path.write_text(html, encoding='utf-8')

css_marker = 'DOWNLOAD_REQUIREMENTS_STYLE_V1'
if css_marker not in css:
    css += '''\n\n/* DOWNLOAD_REQUIREMENTS_STYLE_V1 */\n.download-requirements{grid-column:1/-1;margin-top:4px;padding:24px;border-radius:22px}\n.download-requirements>.requirements-grid{margin-top:20px}\n.download-requirements .req-card{background:rgba(var(--veil-rgb),.018);box-shadow:none}\n@media(max-width:800px){.download-requirements{padding:20px}}\n@media(max-width:480px){.download-requirements{padding:16px}}\n'''
    css_path.write_text(css, encoding='utf-8')

print('download requirements patch applied')
